-- GENERATED by `wfj generate` from data/gossip/gossip-72.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7202e1a20f899faa"] = { "Dobbiamo essere vicini, comandante. Sento gli elementi agitarsi.", "." },
  ["7204696ecddab796"] = { "Se riesci a completare un mazzo di carte degli elementali, riceverai in premio una carta di Lunacupa superiore, la Carta di Lunacupa: Maelstrom. Questa carta a volte colpisce il nemico che stai combattendo, infliggendo ingenti danni.", "." },
  ["720aeef3c6eac440"] = { "Una volta acceso il fuoco da campo, puoi sistemarci intorno ogni sorta di attrezzatura da accampamento.", "." },
  ["7212a9cf7bd77de5"] = { "%s cerca di afferrare il suo pugnale avvelenato!", "." },
  ["7216fd92c01f0438"] = { "{name} arriva di corsa da questa parte! Preparatevi all'attacco!", "." },
  ["72195624212122c9"] = { "Ho sentito che il vecchio maresciallo McBride ti mandava da me.", "." },
  ["721f508e53ee0553"] = { "Temo di non essere più gentile né umile. L'età e innumerevoli battaglie mi hanno indurito la pelle e l'anima. Forse è per questo che Cairne mi ha dato un incarico al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧... i venti gentili e il sole caldo leniscono il dolore.", "." },
  ["722e9c43ed1728c0"] = { "A quanto ho capito, <caro/cara>, è stato raccolto tutto e l'ultimo materiale viene assemblato e spedito alla ⟦Cenarion Hold=Fortezza Cenariana⟧. Le ultime casse dovrebbero arrivare in meno di $2113w giorni. Quando il nostro equipaggiamento e le nostre forze saranno tutti lì, chi porta lo Scettro delle Sabbie Mutevoli potrà suonare il gong vicino ad ⟦Ahn'Qiraj=Ahn'qiraj⟧ per aprire le porte. Allora la guerra avrà inizio.", "." },
  ["723c1b35cb3e262a"] = { "Ti insegnerò, ma prima devi dimostrare quanto vali...", "." },
  ["723fd776f65dab64"] = { "L'anziano Morningdew si è messo a osservare il trambusto alla ⟦Mirage Raceway=Pista dei Miraggi⟧, a ⟦Thousand Needles=Millepicchi⟧.", "." },
  ["72411e7f71a2cece"] = { "{class}, ci serve il tuo aiuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Ci aiuterai nella nostra lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧?", "." },
  ["72468878883cef22"] = { "Come se non avessimo già abbastanza problemi, tu vai e ne crei altri!", "." },
  ["7247755d0bbe0563"] = { "<Copia il modello nel diario.>", "." },
  ["7248805c499bf8f0"] = { "Bravo! Ora rimettilo sul mucchio di ossa.", "." },
  ["724cf9115a48216b"] = { "Te la cavi meglio di me in questo lavoro! Ti serve qualcuno con ancora più esperienza di me: il dottor Herbert Halsey, un non morto che lavora nell'Apothecarium di ⟦Undercity=Sepulcra⟧.", "." },
  ["724f9dcc5205b767"] = { "Che promozioni hai?", "." },
  ["724ff2bf8dab6283"] = { "La carne mi piace extra croccante!", "." },
  ["7255d8be53ca4ac5"] = { "Oh, sono tanto felice che tu sia <tornato/tornata>, {name}.\n\nLo spirito di mio fratello ora è libero dalla corruzione, ma io scelgo di restare qui, nel mio lutto.\n\nGrazie infinite per il tuo aiuto, {name}.", "." },
  ["72579e89864ccc24"] = { "Ma non doveva andare così. Mentre i nemici incalzavano, l'armatura di Anathera fu trafitta dalla lama contaminata di un demone. Nel pieno della battaglia, nulla avrebbe potuto salvarla.", "." },
  ["725d2afba370359a"] = { "Sei impaziente, ed è un bene. Tuttavia, non sei ancora <pronto/pronta> ad addestrarti con quelli come me.", "." },
  ["725ef9e38632337e"] = { "Kergul Bloodaxe, sull'⟦Hunter Rise=Altura dei Cacciatori⟧, è pronto ad aiutarti a raggiungere la ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", "." },
  ["727ba1e2e501573d"] = { "Questo molo? Be', qui puoi prendere la nave che va in quel posto degli elfi della notte. Come si chiama? Ehm, Auberdine, credo. Non lo so con certezza, io carico e scarico roba e basta.", "." },
  ["727d88788811ff38"] = { "%s finisce sulla Flame of Uzel.", "." },
  ["72854be5b91f4947"] = { "Mi fa piacere dirti che il tuo talento ha superato il mio. Ora vattene. Ehm, prova dalla tauren Una, nelle botteghe a nord-ovest dell'altopiano centrale di Picco del Tuono. È molto abile, te lo assicuro.", "." },
  ["72888b8e34057329"] = { "Un campione puro è un campione non corrotto da influenze involontarie. Dobbiamo trovare le creature nell'ambiente più semplice e normale possibile.\n\nCioè in un posto privo di civiltà e degli effetti delle razze dominanti di Azeroth. Un posto... incontaminato.", "." },
  ["728aba0a6339203d"] = { "Aonda è una brava donna e una vera servitrice di Zephras Isle. Spero che tu riesca a guadagnarti presto la sua fiducia e ad aiutarla a proteggere Shen'dar Village. Che i venti ti guidino, {name}.", "." },
  ["7291cdf61a7c38d6"] = { "Hai perso il senno, Nefarius. Parli per enigmi.", "." },
  ["7296d618ddb1cdbd"] = { "Forse hai la stoffa, forse no. Se ce l'hai, ti prenderò con me e ti insegnerò ciò che vuoi sapere. Se non ce l'hai... beh, lasciamo stare.", "." },
  ["729860b8642a200a"] = { "È con soddisfazione che ti comunico che abbiamo raccolto tutto il loto purpureo che ci serve. Grazie per il tuo contributo, {class}. Se ti va, qui ci sono probabilmente altri che stanno ancora raccogliendo altre risorse per la causa.", "." },
  ["729d3774427efbcd"] = { "Aiutami a scegliere con saggezza.", "." },
  ["729d4684ca98e539"] = { "Mi sa che ho perso il distillatore, Mux. L'ho lasciato qui per caso?", "." },
  ["729da9a947bf874b"] = { "Accesso: ⟦Minor Recombobulator=Tecno-Ricostituente Minore⟧", "." },
  ["72a7d4b8c261a860"] = { "Aiuto! Aiuto! Assassini sulle colline! All'armi! All'armi!", "." },
  ["72a816c83e4ad8c4"] = { "Allora va' da Una, dagli armaioli di ⟦Thunder Bluff=Picco del Tuono⟧. Li trovi sull'altura di mezzo.", "." },
  ["72ab257f248757ce"] = { "Come osi comunicare con un duca del Concilio, verme!", "." },
  ["72acd038ec272037"] = { "Scholomance si trova nelle cripte sotto il maniero di Caer Darrow. Un tempo appartenuto alla nobile famiglia Barov, il maniero cadde in rovina dopo la Seconda Guerra. Quando il mago Kel'Thuzad reclutava seguaci per il suo Cult of the Damned, spesso prometteva l'immortalità a chi serviva il suo Re dei Lich. I Barov caddero sotto la sua influenza e donarono il maniero, ma i cultisti sterminarono la famiglia e trasformarono le cripte in una scuola di negromanzia. Anche se Kel'Thuzad non vi risiede più, cultisti e insegnanti sono ancora lì.", "." },
  ["72acd473b31118e0"] = { "Faresti meglio ad andare a ⟦Stormwind=Roccavento⟧, nel Dwarven District, se vuoi imparare a estrarre minerali. Di certo uno dei nani lì può insegnarti la professione.", "." },
  ["72bc2f7eb9376cbb"] = { "Devi avere la reputazione Osannato presso gli gnomi degli Gnomeregan Exiles prima che ti insegni a pilotare un Tecnostruzzo, {class}.", "." },
  ["72be773e89c4e562"] = { "Per servire la Dama Oscura e Varimathras dobbiamo far avanzare il fronte contro l'Infestazione Umana.", "." },
  ["72c368970937975b"] = { "Che vengano pure! Non ho paura di qualche bestia rachitica!", "." },
  ["72c69bed8f4b9650"] = { "Gli Hakkari ti temono, {name}. Parlano di orrori che credevano potesse compiere solo il loro dio senza volto. Li hai bruciati con la forza di Kajaro. Ora conoscono la paura in due luoghi.\n\nÈ ora di rafforzare ancora il ciottolo. Dammi il talismano.", "." },
  ["72d30164f1e1be27"] = { "Ad alcuni è stata risparmiata l'angoscia che i ricordi portano.", "." },
  ["72dc4d6fb8f91814"] = { "Anche se la tua fiducia nelle mie capacità mi lusinga, insegnarti va oltre la mia abilità. Devi andare alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus e parlare con l'elfa della notte Ainethil. Lei può aiutarti.", "." },
  ["72ddc966497c85ec"] = { "Chissà se la tua bambolina sa nuotare!", "." },
  ["72de22fa9de8f0b6"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quei murloc con la Luce dalla mia parte!", "." },
  ["72e49cbd5e38ada1"] = { "Ti sembra che abbia tempo da perdere in chiacchiere?", "." },
  ["72eb9a3d1a09f811"] = { "Violenza! Danni alla proprietà! Nessuno passerà!!", "." },
  ["72ec59cb74ed4858"] = { "Hai la mia lama??", "." },
})
